import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Module: handl_plugin_module","description":"","frontmatter":{},"headers":[],"relativePath":"api/host/handl_plugin_module/handl_plugin_module.md","filePath":"api/host/handl_plugin_module/handl_plugin_module.md"}`),a={name:`api/host/handl_plugin_module/handl_plugin_module.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p><strong>handl_plugin_module</strong></p><h1 id="module-handl-plugin-module" tabindex="-1">Module: handl_plugin_module <a class="header-anchor" href="#module-handl-plugin-module" aria-label="Permalink to “Module: handl_plugin_module”">​</a></h1><h2 id="contents" tabindex="-1">Contents <a class="header-anchor" href="#contents" aria-label="Permalink to “Contents”">​</a></h2><p><strong>Structs</strong></p><ul><li><a href="#moduleregistry"><code>ModuleRegistry</code></a> - A registry of [<code>Module</code>]s providing qualified function lookup.</li><li><a href="#modulerule"><code>ModuleRule</code></a> - A [<code>Contribution</code>] that registers a single [<code>Module</code>] with a</li><li><a href="#moduleruntime"><code>ModuleRuntime</code></a> - A [<code>Plugin</code>] + [<code>RuleAcceptor</code>] that accepts [<code>ModuleRule</code>] contributions</li></ul><hr><h2 id="handl-plugin-module-moduleregistry" tabindex="-1">handl_plugin_module::ModuleRegistry <a class="header-anchor" href="#handl-plugin-module-moduleregistry" aria-label="Permalink to “handl_plugin_module::ModuleRegistry”">​</a></h2><p><em>Struct</em></p><p>A registry of [<code>Module</code>]s providing qualified function lookup.</p><p><code>ModuleRegistry</code> implements [<code>ModuleLookup</code>]. It splits a qualified name on the first <code>.</code>: the left segment is the module name, the right segment is the function name within that module. For example, <code>math.add</code> resolves to module <code>&quot;math&quot;</code>, function <code>&quot;add&quot;</code>.</p><p>If the name contains no <code>.</code>, the registry searches all modules in registration order and returns the first match. This allows flat names (e.g. <code>add</code>) to coexist with qualified names (e.g. <code>math.add</code>).</p><h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to “Architecture”">​</a></h1><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>       ModuleRegistry</span></span>
<span class="line"><span>           │</span></span>
<span class="line"><span>           │ lookup(&quot;math.add&quot;)</span></span>
<span class="line"><span>           ▼</span></span>
<span class="line"><span>     split on &quot;.&quot;</span></span>
<span class="line"><span>      ┌────┴────┐</span></span>
<span class="line"><span>      ▼         ▼</span></span>
<span class="line"><span>  &quot;math&quot;     &quot;add&quot;</span></span>
<span class="line"><span>      │         │</span></span>
<span class="line"><span>      ▼         ▼</span></span>
<span class="line"><span>   Module    Function</span></span></code></pre></div><p>The eval layer sees only the [<code>ModuleLookup</code>] interface — it does not know about modules.</p><p><strong>Fields:</strong></p><ul><li><code>modules: Vec&lt;std::sync::Arc&lt;dyn Module&gt;&gt;</code></li></ul><p><strong>Methods:</strong></p><ul><li><code>fn new() -&gt; Self</code> - Create a new empty registry.</li><li><code>fn with&lt;impl Module + Send + Sync + &#39;static&gt;(self: Self, module: impl Trait) -&gt; Self</code> - Register a module (builder style).</li><li><code>fn register&lt;impl Module + Send + Sync + &#39;static&gt;(self: &amp; mut Self, module: impl Trait)</code> - Register a module (mutating).</li><li><code>fn register_arc(self: &amp; mut Self, module: Arc&lt;dyn Module&gt;)</code> - Register an already-<code>Arc</code>ed module (mutating).</li><li><code>fn module_count(self: &amp;Self) -&gt; usize</code> - Returns the number of registered modules.</li><li><code>fn module_names(self: &amp;Self) -&gt; impl Trait</code> - Returns an iterator over the registered module names.</li><li><code>fn module(self: &amp;Self, name: &amp;str) -&gt; Option&lt;&amp;Arc&lt;dyn Module&gt;&gt;</code> - Look up a module by name.</li></ul><p><strong>Trait Implementations:</strong></p><ul><li><strong>Default</strong><ul><li><code>fn default() -&gt; Self</code></li></ul></li><li><strong>Debug</strong><ul><li><code>fn fmt(self: &amp;Self, f: &amp; mut std::fmt::Formatter) -&gt; std::fmt::Result</code></li></ul></li><li><strong>Clone</strong><ul><li><code>fn clone(self: &amp;Self) -&gt; Self</code></li></ul></li><li><strong>ModuleLookup</strong><ul><li><code>fn lookup(self: &amp;Self, qualified_name: &amp;str) -&gt; Option&lt;&amp;dyn Function&gt;</code></li><li><code>fn lookup_type_signature(self: &amp;Self, qualified_name: &amp;str) -&gt; Option&lt;Value&gt;</code></li><li><code>fn lookup_module_exports(self: &amp;Self, module_name: &amp;str) -&gt; Option&lt;Vec&lt;(String, Option&lt;Value&gt;)&gt;&gt;</code></li></ul></li></ul><h2 id="handl-plugin-module-modulerule" tabindex="-1">handl_plugin_module::ModuleRule <a class="header-anchor" href="#handl-plugin-module-modulerule" aria-label="Permalink to “handl_plugin_module::ModuleRule”">​</a></h2><p><em>Struct</em></p><p>A [<code>Contribution</code>] that registers a single [<code>Module</code>] with a [<code>ModuleRuntime</code>] [<code>RuleAcceptor</code>].</p><p>This wraps a module in an <code>Arc</code> so it can be passed through the platform contribution pipeline via <code>ctx.contribute::&lt;ModuleRuntime&gt;(ModuleRule::new(MyModule))</code>.</p><p><strong>Tuple Struct</strong>: <code>(std::sync::Arc&lt;dyn Module&gt;)</code></p><p><strong>Methods:</strong></p><ul><li><code>fn new&lt;impl Module + Send + Sync + &#39;static&gt;(module: impl Trait) -&gt; Self</code> - Wrap a module for contribution to a [<code>ModuleRuntime</code>].</li><li><code>fn from_arc(module: Arc&lt;dyn Module&gt;) -&gt; Self</code> - Wrap an already-<code>Arc</code>ed module for contribution.</li></ul><p><strong>Trait Implementations:</strong></p><ul><li><strong>Contribution</strong><ul><li><code>fn id(self: &amp;Self) -&gt; &amp;str</code></li></ul></li></ul><h2 id="handl-plugin-module-moduleruntime" tabindex="-1">handl_plugin_module::ModuleRuntime <a class="header-anchor" href="#handl-plugin-module-moduleruntime" aria-label="Permalink to “handl_plugin_module::ModuleRuntime”">​</a></h2><p><em>Struct</em></p><p>A [<code>Plugin</code>] + [<code>RuleAcceptor</code>] that accepts [<code>ModuleRule</code>] contributions and provides function lookup via the accumulated [<code>ModuleRegistry</code>].</p><p>Ported from <code>plugin-vm-common::host::host::ModuleRuntime</code>. The old <code>ModuleRuntime</code> implemented the VM&#39;s <code>CallableLookup&lt;V&gt;</code> trait; this new version implements the platform&#39;s non-generic [<code>ModuleLookup</code>] trait instead. Hosts register a <code>ModuleRuntime</code> plugin, library plugins contribute <code>ModuleRule</code>s into it, and the host wires the runtime&#39;s registry into <code>EvalContext</code> via <code>set_modules</code>.</p><h1 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to “Example”">​</a></h1><div class="language-ignore"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ignore</span><pre class="shiki shiki-themes handl-dark github-light" style="--shiki-dark:#ffffff;--shiki-light:#24292e;--shiki-dark-bg:#2a2a2a;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span>use std::rc::Rc;</span></span>
<span class="line"><span>use handl_platform::{DefaultHost, ModuleLookup};</span></span>
<span class="line"><span>use handl_plugin_module::{ModuleRuntime, ModuleRule, ModuleRegistry};</span></span>
<span class="line"><span></span></span>
<span class="line"><span>let mut host = DefaultHost::default();</span></span>
<span class="line"><span>host.register_plugin(ModuleRuntime::new());</span></span>
<span class="line"><span>// ... library plugins contribute ModuleRule(MyModule) ...</span></span>
<span class="line"><span>host.load();</span></span>
<span class="line"><span>let runtime = host.plugins_mut().get_plugin_mut::&lt;ModuleRuntime&gt;().unwrap();</span></span>
<span class="line"><span>let registry: Rc&lt;dyn ModuleLookup&gt; = Rc::new(runtime.registry().clone());</span></span></code></pre></div><p><strong>Fields:</strong></p><ul><li><code>registry: ModuleRegistry</code></li></ul><p><strong>Methods:</strong></p><ul><li><code>fn new() -&gt; Self</code> - Create a new empty <code>ModuleRuntime</code>.</li><li><code>fn with&lt;impl Module + Send + Sync + &#39;static&gt;(self: Self, module: impl Trait) -&gt; Self</code> - Register a module directly (builder style).</li><li><code>fn module_count(self: &amp;Self) -&gt; usize</code> - Returns the number of registered modules.</li><li><code>fn registry(self: &amp;Self) -&gt; &amp;ModuleRegistry</code> - Borrow the underlying [<code>ModuleRegistry</code>].</li></ul><p><strong>Trait Implementations:</strong></p><ul><li><strong>Plugin</strong><ul><li><code>fn id(self: &amp;Self) -&gt; &amp;str</code></li><li><code>fn name(self: &amp;Self) -&gt; &amp;str</code></li><li><code>fn capabilities(self: &amp;Self) -&gt; &amp;[CapabilityId]</code></li><li><code>fn metadata(self: &amp;Self, _capability: &amp;CapabilityId) -&gt; Option&lt;CapabilityMetadata&gt;</code></li><li><code>fn run(self: &amp;Self, _request: &amp;CapabilityRequest, _ctx: &amp; mut PluginContext) -&gt; Result&lt;CapabilityResponse, PlatformError&gt;</code></li><li><code>fn module_lookup(self: &amp;Self) -&gt; Option&lt;std::rc::Rc&lt;dyn handl_platform::ModuleLookup&gt;&gt;</code></li></ul></li><li><strong>Default</strong><ul><li><code>fn default() -&gt; Self</code></li></ul></li><li><strong>Clone</strong><ul><li><code>fn clone(self: &amp;Self) -&gt; Self</code></li></ul></li><li><strong>ModuleLookup</strong><ul><li><code>fn lookup(self: &amp;Self, qualified_name: &amp;str) -&gt; Option&lt;&amp;dyn Function&gt;</code></li><li><code>fn lookup_type_signature(self: &amp;Self, qualified_name: &amp;str) -&gt; Option&lt;Value&gt;</code></li><li><code>fn lookup_module_exports(self: &amp;Self, module_name: &amp;str) -&gt; Option&lt;Vec&lt;(String, Option&lt;Value&gt;)&gt;&gt;</code></li></ul></li><li><strong>RuleAcceptor</strong><ul><li><code>fn accept(self: &amp; mut Self, rule: ModuleRule) -&gt; Result&lt;(), PlatformError&gt;</code></li></ul></li></ul>`,41)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};